const crypto = require('crypto');
function timingSafeEqualHex(a, b) {
  try {
    const ba = Buffer.from(String(a).trim(), 'hex');
    const bb = Buffer.from(String(b).trim(), 'hex');
    if (ba.length !== bb.length) return false;
    return crypto.timingSafeEqual(ba, bb);
  } catch {
    return false;
  }
}
const secret = String($env.N8N_WEBHOOK_HMAC_SECRET || '').trim();
const item = $input.first().json;
const headers = item.headers || {};
const sigHeader = headers['x-bridge-signature'] || headers['X-Bridge-Signature'] || '';
const m = /^sha256=(.+)$/i.exec(String(sigHeader));
const digestFromHeader = m ? m[1].trim() : '';
const body = item.body || {};
const clinic_id = typeof body.clinic_id === 'number' ? body.clinic_id : (Number.parseInt(String(body.clinic_id || '1').replace(/[^0-9]/g, ''), 10) || 1);
const sender = String(body.sender || body.from || '').trim();
const from = String(body.from || body.sender || '').trim();
const text = String(body.text || '');
const messageId = String(body.messageId || '');
const timestamp = body.timestamp;
const receivedAt = String(body.receivedAt || '');
const canonicalObj = { clinic_id, sender: sender || from, from: from || sender, text, messageId, timestamp, receivedAt };
const raw = JSON.stringify(canonicalObj);
let hmacOk = true;
if (secret) {
  const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
  hmacOk = timingSafeEqualHex(expected, digestFromHeader);
}
return [{ json: { ...item, hmacOk, hmacChecked: Boolean(secret) } }];

const hashText = (input) => {
  const source = String(input || '');
  let hash = 0;
  for (let i = 0; i < source.length; i += 1) {
    hash = ((hash << 5) - hash) + source.charCodeAt(i);
    hash |= 0;
  }
  return `h${Math.abs(hash)}`;
};

const body = $json.body || {};
const clinicIdRaw = String(body.clinic_id || '1').trim();
const clinic_id = Number.parseInt(clinicIdRaw.replace(/[^0-9]/g, ''), 10) || 1;
const workflowStartedAt = Date.now();
const from = String(body.from || body.sender || '').trim();
const text = String(body.text || '').trim();
const messageId = String(body.messageId || '');
const words = text.toLowerCase();

const bookingKeywords = ['حجز', 'موعد', 'appointment', 'book', 'reserve'];
const pricingKeywords = ['سعر', 'كم', 'تكلفة', 'price', 'cost'];
const emergencyKeywords = ['طوارئ', 'نزيف', 'ألم شديد', 'الم شديد', 'urgent', 'emergency'];

const clinicTimezone = 'Asia/Amman';
const startHour = 9;
const endHour = 21;
const nowHour = Number(new Date().toLocaleString('en-US', { hour: 'numeric', hour12: false, timeZone: clinicTimezone }));
const outsideHours = nowHour < startHour || nowHour >= endHour;

const contains = (arr) => arr.some((k) => words.includes(k));
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

let ruleIntent = 'GENERAL';
if (contains(emergencyKeywords)) ruleIntent = 'URGENT';
else if (contains(bookingKeywords)) ruleIntent = 'BOOKING';
else if (contains(pricingKeywords)) ruleIntent = 'PRICING';

const priorityMap = { URGENT: 1, BOOKING: 2, PRICING: 3, GENERAL: 4 };
const rulePriority = priorityMap[ruleIntent] || 4;
const ruleHandoff = ruleIntent === 'URGENT';

let fallbackReply;
if (outsideHours) {
  fallbackReply = pick([
    'وصلتنا رسالتك، الدوام حالياً مغلق. سنعاود الرد عند بدء الدوام بإذن الله.',
    'شكراً لتواصلك، نحن خارج أوقات الدوام الآن وسنرد عليك أول ما يبدأ الدوام.'
  ]);
} else if (ruleIntent === 'URGENT') {
  fallbackReply = pick([
    'تم استلام رسالتك بشكل عاجل. إذا كانت الحالة طارئة جداً يرجى التواصل مباشرة مع الطوارئ، وسيتم تحويل رسالتك للفريق حالاً.',
    'وصلتنا حالتك كأولوية. في حال وجود خطر مباشر يرجى التوجه للطوارئ فوراً، وسنتابع معك بأسرع وقت.'
  ]);
} else if (ruleIntent === 'BOOKING') {
  fallbackReply = pick([
    'أهلاً بك، تم استلام طلب الحجز. أرسل اسم المريض ورقم الهاتف والوقت المناسب وسننسق الموعد.',
    'تم استلام طلب الموعد. من فضلك أرسل الاسم الثلاثي ورقم الهاتف والفترة المناسبة للحجز.'
  ]);
} else if (ruleIntent === 'PRICING') {
  fallbackReply = pick([
    'الأسعار تختلف حسب الحالة، أرسل تفاصيل أكثر وسنوضح التكلفة المناسبة.',
    'حتى نحدد السعر بدقة، يرجى توضيح نوع الحالة أو الخدمة المطلوبة.'
  ]);
} else {
  fallbackReply = pick([
    'تم استلام رسالتك، وسيقوم فريق العيادة بالرد عليك قريباً.',
    'وصلتنا رسالتك بنجاح، نشكرك على تواصلك وسنرد عليك بأقرب وقت.'
  ]);
}

const dedupeHash = hashText([from, messageId, text].join('::'));

return [{
  json: {
    from,
    to: from,
    text,
    messageId,
    receivedAt: new Date().toISOString(),
    outsideHours,
    alertTo: '9639XXXXXXXXX@c.us',
    dedupeHash,
    ruleIntent,
    rulePriority,
    ruleHandoff,
    fallbackReply,
    clinic_id,
    workflowStartedAt
  }
}];

const j = $input.first().json;
const b = j.body && typeof j.body === 'object' && !Array.isArray(j.body) ? j.body : {};
return [{ json: { ...j, ...b } }];

const crm = $input.first().json;
async function main() {
  const base = $env.OPS_DASHBOARD_URL || "http://host.docker.internal:3001";
  const token = $env.SCHEDULING_SERVICE_TOKEN || "";
  if (!token) {
    return {
      ...crm,
      finalIntent: crm.ruleIntent,
      finalPriority: crm.rulePriority,
      finalReply: crm.fallbackReply,
      handoffRequired: crm.ruleHandoff,
      decisionSource: "rules",
      aiValid: false,
      aiFailureReason: "no_service_token",
    };
  }
  try {
    const r1 = await fetch(base + "/api/internal/scheduling/interpret", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
      body: JSON.stringify({ text: crm.text }),
    });
    let int;
    try {
      int = await r1.json();
    } catch {
      throw new Error("interpret_bad_json");
    }
    if (!r1.ok || !int || !int.ok || !int.interpret) {
      const msg = (int && (int.error || int.detail)) || "interpret_http_" + r1.status;
      throw new Error(String(msg));
    }
    const intent = int.interpret.intent;
    if (intent === "urgent") {
      return {
        ...crm,
        finalIntent: "URGENT",
        finalPriority: 1,
        finalReply:
          crm.fallbackReply ||
          "تم استلام حالتك كأولوية. إذا كانت الحالة طارئة جداً يرجى التواصل مع الطوارئ.",
        handoffRequired: true,
        decisionSource: "scheduling_interpret",
        aiValid: false,
        aiFailureReason: "n/a",
      };
    }
    if (intent !== "booking") {
      return {
        ...crm,
        finalIntent: crm.ruleIntent,
        finalPriority: crm.rulePriority,
        finalReply: crm.fallbackReply,
        handoffRequired: crm.ruleHandoff,
        decisionSource: "rules",
        aiValid: false,
        aiFailureReason: "not_booking",
      };
    }
    const r2 = await fetch(base + "/api/internal/scheduling/slots", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
      body: JSON.stringify({
        clinic_id: Number(crm.clinic_id),
        conversation_id: Number(crm.conversation_id),
        specialty: int.interpret.specialty || undefined,
      }),
    });
    let slots;
    try {
      slots = await r2.json();
    } catch {
      throw new Error("slots_bad_json");
    }
    if (!r2.ok || !slots || !slots.ok) {
      const msg = (slots && (slots.error || slots.detail)) || "slots_http_" + r2.status;
      throw new Error(String(msg));
    }
    const lines = (slots.reply_lines || []).join("\n");
    const closed = slots.closed_message_ar;
    const finalReply = lines
      ? "أهلاً بك، أقرب المواعيد المتاحة:\n" + lines + "\nأرسل رقم الخيار (1، 2، أو 3)."
      : closed || crm.fallbackReply;
    return {
      ...crm,
      finalIntent: "BOOKING",
      finalPriority: 2,
      finalReply,
      handoffRequired: false,
      decisionSource: "scheduling_engine",
      aiValid: false,
      aiFailureReason: "n/a",
      schedulingSlots: slots.slots,
    };
  } catch (e) {
    return {
      ...crm,
      finalIntent: crm.ruleIntent,
      finalPriority: crm.rulePriority,
      finalReply: crm.fallbackReply,
      handoffRequired: crm.ruleHandoff,
      decisionSource: "rules",
      aiValid: false,
      aiFailureReason: String(e && e.message),
    };
  }
}
return main().then((j) => [{ json: j }]);

const item = $input.first().json;
const success = !item.error && (item.ok !== false);
const retries = Number(item.sendRetries || 0);
return [{ json: { ...item, sendSucceeded: success, sendRetries: retries, sendFailureReason: success ? null : (item.error?.message || item.message || 'send_failed') } }];

const row = $input.first().json;
let b = row;
if (row && row.body && typeof row.body === 'object' && !Array.isArray(row.body)) b = row.body;
const ok = b.ok !== false && !b.error;
const dup = Boolean(b.duplicate);
const sendSucceeded = ok && (dup ? true : b.bridge_send_ok !== false);
return [{ json: {
  ok,
  sent: sendSucceeded,
  sendSucceeded,
  finalIntent: String(b.finalIntent || ''),
  replyText: String(b.reply_text || ''),
  decisionSource: String(b.decision_source || ''),
  sendRetries: 0,
  sendFailureReason: String(b.bridge_send_error || b.error || ''),
  duplicate: dup
} }];
